    preChargeComplete = false;
    batteryStatus = false;
    inverterSleepStatus = false;

    /* Inverter */
    pinMode(invPreCharge, OUTPUT);
    pinMode(invSolenoid, OUTPUT);
    pinMode(invPowerPin, OUTPUT);
